CREATE OR REPLACE FUNCTION public.territory_gather_claim()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_uid uuid:=auth.uid(); v_resource text; v_qty bigint;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE='28000'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(v_uid::text),7724);
 DELETE FROM public.territory_gather_jobs WHERE player_id=v_uid AND finishes_at<=clock_timestamp()
 RETURNING resource_id INTO v_resource;
 IF v_resource IS NULL THEN RETURN jsonb_build_object('error','not_ready_or_no_job'); END IF;
 INSERT INTO public.territory_resource_wallet AS wallet(player_id,resource_id,quantity)
 VALUES(v_uid,v_resource,1)
 ON CONFLICT(player_id,resource_id) DO UPDATE SET quantity=wallet.quantity+1
 RETURNING quantity INTO v_qty;
 RETURN jsonb_build_object('success',true,'resource_id',v_resource,'quantity',v_qty);
END;
$function$

CREATE OR REPLACE FUNCTION public.territory_gather_start(p_resource_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_uid uuid:=auth.uid(); v_finish timestamptz;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE='28000'; END IF;
 IF p_resource_id IS NULL OR p_resource_id NOT IN ('gather-wood','gather-herb','gather-ore','gather-crystal','gather-hide')
 THEN RETURN jsonb_build_object('error','invalid_resource'); END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(v_uid::text),7724);
 IF EXISTS (SELECT 1 FROM public.territory_gather_jobs WHERE player_id=v_uid)
 THEN RETURN jsonb_build_object('error','already_gathering'); END IF;
 v_finish:=clock_timestamp()+interval '4 hours';
 INSERT INTO public.territory_gather_jobs(player_id,resource_id,started_at,finishes_at)
 VALUES(v_uid,p_resource_id,clock_timestamp(),v_finish);
 RETURN jsonb_build_object('success',true,'resource_id',p_resource_id,'finishes_at',v_finish);
END;
$function$

CREATE OR REPLACE FUNCTION public.territory_gather_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_uid uuid := auth.uid(); v_active jsonb; v_wallet jsonb;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE='28000'; END IF;
 SELECT jsonb_build_object('resource_id',j.resource_id,'finishes_at',j.finishes_at)
 INTO v_active FROM public.territory_gather_jobs j WHERE j.player_id=v_uid;
 SELECT coalesce(jsonb_object_agg(w.resource_id,w.quantity),'{}'::jsonb)
 INTO v_wallet FROM public.territory_resource_wallet w WHERE w.player_id=v_uid;
 RETURN jsonb_build_object('active',v_active,'wallet',v_wallet,'server_now',clock_timestamp());
END;
$function$

CREATE OR REPLACE FUNCTION public.territory_profession_unlock(p_profession text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_uid uuid:=auth.uid(); v_player public.players%ROWTYPE; v_existing text; v_after int;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE='28000'; END IF;
 IF p_profession IS NULL OR p_profession NOT IN ('smith','alchemist','artisan','jeweler','engineer')
 THEN RETURN jsonb_build_object('error','invalid_profession'); END IF;
 SELECT * INTO v_player FROM public.players WHERE id=v_uid FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('error','player_not_found'); END IF;
 SELECT profession INTO v_existing FROM public.territory_profession_unlocks WHERE player_id=v_uid;
 IF v_existing IS NOT NULL THEN
   IF v_existing<>p_profession THEN RETURN jsonb_build_object('error','only_one_profession'); END IF;
   RETURN jsonb_build_object('success',true,'profession',v_existing,'gems_after',v_player.gems,'already_owned',true);
 END IF;
 IF v_player.gems<1000 OR coalesce((v_player.game_state->'player'->>'gems')::int,0)<1000
 THEN RETURN jsonb_build_object('error','insufficient_gems'); END IF;
 v_after:=v_player.gems-1000;
 UPDATE public.players SET gems=v_after, game_state=jsonb_set(
    jsonb_set(coalesce(v_player.game_state,'{}'::jsonb),'{player}',
      coalesce(v_player.game_state->'player','{}'::jsonb)||jsonb_build_object('gems',v_after),true),
    '{professions}',
    coalesce(v_player.game_state->'professions','{}'::jsonb)||jsonb_build_object('active',p_profession),true)
 WHERE id=v_uid;
 INSERT INTO public.territory_profession_unlocks(player_id,profession) VALUES(v_uid,p_profession);
 RETURN jsonb_build_object('success',true,'profession',p_profession,'gems_after',v_after);
END;
$function$
